package ru.secondmemory;
import android.app.*;
import android.content.*;
import android.os.*;
import android.text.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.time.*;
import java.time.format.*;
import java.util.*;

/** One-tap recall by calendar day with a short digest and inspectable sources. */
public class AnalysisActivity extends Activity {
 private TextView status,heading;private EditText search;private CheckBox detailed;private LinearLayout list;private Button start,retryButton;private ProgressBar progress;private int totalCount,processedCount;
 private LocalDate selected;private String report="",lastSignature="";private volatile boolean loading;private boolean dirty;private long refreshed;private Map<String,TaskDb.Row> tasks=new HashMap<>();private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable tick=new Runnable(){public void run(){updateStatus();if(System.currentTimeMillis()-refreshed>3000)refresh();handler.postDelayed(this,1000);}};
 private void updateStatus(){if(status==null)return;boolean running=AnalysisService.running||AiJob.isActive();boolean paused=getSharedPreferences("ai",0).getBoolean("paused",false);String error=getSharedPreferences("ai",0).getString("last_error","");String info=running?AiJob.status:!error.isEmpty()?error:paused?"Анализ на паузе. Прогресс сохранён.":totalCount>0&&processedCount>=totalCount?"Все разговоры за этот период разобраны.":LocalModel.ready(this)?AiJob.status:LocalModel.status(this);Ui.update(status,info);start.setText(running?"Приостановить анализ":LocalModel.ready(this)?"Начать / продолжить анализ":"Подготовить нейросеть");progress.setIndeterminate(running&&processedCount==0);if(!progress.isIndeterminate()){progress.setMax(Math.max(1,totalCount));progress.setProgress(processedCount);}}

 static final class Entry {File dir;JSONObject state;List<ConversationAnalysis.Line> lines;Entry(File d,JSONObject s,List<ConversationAnalysis.Line> l){dir=d;state=s;lines=l;}}
 @Override public void onCreate(Bundle b){super.onCreate(b);if(b!=null&&b.containsKey("day")){String day=b.getString("day","");selected=day.isEmpty()?null:LocalDate.parse(day);}else if("yesterday".equals(getIntent().getStringExtra("day")))selected=LocalDate.now().minusDays(1);
  LinearLayout page=Ui.column(this);setContentView(page);ScreenLayout.apply(this,page);Ui.title(page,"Вспомнить разговоры","");LinearLayout control=Ui.card(page);status=Ui.label(this,"Проверяю очередь анализа…",14);control.addView(status);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);control.addView(progress,new LinearLayout.LayoutParams(-1,Ui.dp(this,8)));start=Ui.button(control,"Начать / продолжить анализ",true,()->{if(AnalysisService.running||AiJob.isActive()){AnalysisService.pause(this);updateStatus();}else begin();});retryButton=Ui.button(control,"Повторить ошибки анализа",false,this::retry);retryButton.setVisibility(android.view.View.GONE);
  ScrollView scroll=new ScrollView(this);LinearLayout content=Ui.column(this);scroll.addView(content);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));heading=label("",19);content.addView(heading);
  HorizontalScrollView dates=new HorizontalScrollView(this);LinearLayout choices=new LinearLayout(this);button(choices,"Вчера",()->select(LocalDate.now().minusDays(1)));button(choices,"Неделю назад",()->select(LocalDate.now().minusDays(7)));button(choices,"Сегодня",()->select(LocalDate.now()));button(choices,"Выбрать дату",this::pickDate);button(choices,"Все дни",()->select(null));dates.addView(choices);content.addView(dates);
  search=new EditText(this);search.setHint("Имя или тема");search.setSingleLine(true);content.addView(search);
  button(content,"Скопировать всю сводку",()->copy(report));detailed=new CheckBox(this);detailed.setText("Подробно — все выводы");detailed.setSingleLine(false);detailed.setMaxLines(3);content.addView(detailed);
  list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(list);
  button(content,"Исходные разговоры за выбранный период",this::rawPeriod);
  button(content,"Поручения и статусы",()->startActivity(new Intent(this,TasksActivity.class)));
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int p,int c,int a){}public void onTextChanged(CharSequence s,int a,int b,int c){refresh();}public void afterTextChanged(Editable e){}});detailed.setOnCheckedChangeListener((v,c)->refresh());
  refresh();if(getIntent().getBooleanExtra("prepare",false)&&b==null)begin();
 }
 private TextView label(String value,int size){return Ui.label(this,value,size);}
 private void button(LinearLayout parent,String value,Runnable r){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setMinHeight(Math.round(48*getResources().getDisplayMetrics().density));b.setOnClickListener(v->r.run());Ui.buttonStyle(b,false);parent.addView(b);}
 private String period(){if(selected==null)return "Все разговоры";String prefix=selected.equals(LocalDate.now().minusDays(1))?"Вчера":selected.equals(LocalDate.now())?"Сегодня":"Разговоры";return prefix+" · "+selected.format(DateTimeFormatter.ofPattern("dd.MM.yyyy"));}
 private void select(LocalDate day){selected=day;refresh();}
 private void pickDate(){LocalDate day=selected==null?LocalDate.now():selected;new DatePickerDialog(this,(v,y,m,d)->select(LocalDate.of(y,m+1,d)),day.getYear(),day.getMonthValue()-1,day.getDayOfMonth()).show();}
 private void begin(){
  if(LocalModel.ready(this)||LocalModel.file(this).length()==LocalModel.SIZE){AnalysisService.startUser(this,getIntent().getStringExtra("session"));Toast.makeText(this,"Анализ запускается",Toast.LENGTH_LONG).show();return;}
  new AlertDialog.Builder(this).setTitle("Подготовить анализ разговоров").setMessage("Нужно один раз скачать Qwen: 1,12 ГБ. После проверки модель будет автоматически разбирать сохранённые разговоры на телефоне. Результаты появятся здесь.")
   .setPositiveButton("Скачать по Wi-Fi",(d,w)->download(true)).setNeutralButton("Через любую сеть",(d,w)->download(false)).setNegativeButton("Назад",null).show();
 }
 private void download(boolean wifi){try{LocalModel.download(this,wifi);Toast.makeText(this,"Загрузка запущена. После неё начнётся анализ разговоров.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
 private void retry(){AnalysisService.pause(this);new Thread(()->{try{long until=System.currentTimeMillis()+30000;while(AnalysisService.running||AiJob.isActive()){if(System.currentTimeMillis()>until)throw new IOException("Предыдущий разбор ещё завершается");Thread.sleep(100);}for(File dir:dirs()){JSONObject state=ConversationAnalysis.load(dir);state.put("failures",0).remove("error");ConversationAnalysis.save(dir,state);}getSharedPreferences("ai",0).edit().remove("last_error").apply();runOnUiThread(()->{AnalysisService.startUser(this,getIntent().getStringExtra("session"));refresh();});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Повтор не запущен: "+e.getMessage(),Toast.LENGTH_LONG).show());}},"analysis-retry").start();}
 private File[] dirs(){File[] dirs=new File(getFilesDir(),"sessions").listFiles(File::isDirectory);if(dirs==null)return new File[0];Arrays.sort(dirs,(a,b)->b.getName().compareTo(a.getName()));return dirs;}
 private void refresh(){if(loading){dirty=true;return;}loading=true;String filter=search.getText().toString().trim().toLowerCase(Locale.ROOT);boolean full=detailed.isChecked();LocalDate day=selected;RecallWindow window=new RecallWindow(day,ZoneId.systemDefault());
  new Thread(()->{List<Entry> entries=new ArrayList<>();String error="";Map<String,TaskDb.Row> taskRows=new HashMap<>();try(TaskDb db=new TaskDb(this)){for(TaskDb.Row row:db.all())taskRows.put(row.id,row);}catch(Exception e){error="Статусы поручений временно недоступны";}
   for(File dir:dirs()){try{List<ConversationAnalysis.Line> lines=new ArrayList<>();for(ConversationAnalysis.Line line:ConversationAnalysis.read(dir))if(window.contains(line.recorded))lines.add(line);if(!lines.isEmpty())entries.add(new Entry(dir,ConversationAnalysis.load(dir),lines));}catch(Exception e){error="Некоторые записи требуют проверки: "+e.getMessage();}}
   String warning=error;StringBuilder stamp=new StringBuilder(filter+"|"+full+"|"+day+"|"+warning);for(Entry e:entries)stamp.append(e.dir.getName()).append(e.state.toString().hashCode()).append(e.lines.size());for(TaskDb.Row row:taskRows.values())stamp.append(row.id).append(row.completed).append(row.text).append(row.assignee).append(row.due);String signature=stamp.toString();runOnUiThread(()->{loading=false;refreshed=System.currentTimeMillis();if(!isFinishing()&&!isDestroyed()&&!signature.equals(lastSignature)){lastSignature=signature;tasks=taskRows;render(entries,filter,full,warning);}if(dirty){dirty=false;refresh();}});
  },"recall-read").start();
 }
 private String sessionTitle(File dir){try{return LocalDateTime.parse(dir.getName(),DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss_SSS")).format(DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm"));}catch(Exception e){return dir.getName();}}
 private ConversationAnalysis.Line line(Entry e,JSONObject point){for(ConversationAnalysis.Line l:e.lines)if(l.id==point.optInt("line"))return l;return null;}
 private TaskDb.Row task(Entry e,JSONObject p){String id=UUID.nameUUIDFromBytes((e.dir.getName()+"\n"+TaskRules.normalize(p.optString("quote"))).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();return tasks.get(id);}
 private String pointText(Entry e,JSONObject p){TaskDb.Row row="task".equals(p.optString("kind"))?task(e,p):null;if(row==null)return p.optString("text")+(p.optString("owner").isEmpty()?"":" · "+p.optString("owner"));return row.text+(row.assignee.isEmpty()?"":" · "+row.assignee)+(row.due==0?"":" · "+Instant.ofEpochMilli(row.due).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("dd.MM HH:mm")));}
 private boolean matches(Entry e,JSONObject p,String filter){return filter.isEmpty()||(pointText(e,p)+" "+p.optString("quote")).toLowerCase(Locale.ROOT).contains(filter);}
 private String title(String kind){if("topic".equals(kind)||"fact".equals(kind))return "О чём говорили";if("decision".equals(kind))return "Что решили";if("promise".equals(kind))return "Кто что обещал";if("task".equals(kind))return "Что осталось сделать";if("question".equals(kind))return "Что осталось выяснить";return "Что нужно проверить";}
 private void render(List<Entry> entries,String filter,boolean full,String warning){heading.setText(period());list.removeAllViews();StringBuilder text=new StringBuilder(period()+"\n");int total=0,processed=0;for(Entry e:entries)for(ConversationAnalysis.Line l:e.lines){total++;if(l.id<=e.state.optInt("cursor"))processed++;}totalCount=total;processedCount=processed;boolean failed=false;for(Entry item:entries)if(item.state.optInt("failures",0)>0)failed=true;retryButton.setVisibility(failed?android.view.View.VISIBLE:android.view.View.GONE);updateStatus();String progress="Записей: "+entries.size()+" · разобрано фрагментов: "+processed+" из "+total;list.addView(label(progress,13));text.append(progress).append('\n');if(!warning.isEmpty())list.addView(label(warning,14));
  if(total==0){String empty="За этот период сохранённых разговоров нет. Выбери другую дату или «Все дни».";list.addView(label(empty,16));text.append(empty).append('\n');}
  else if(processed<total){String pending=AnalysisService.running||AiJob.isActive()?"Идёт разбор. Новые выводы появятся автоматически.":"Есть неразобранные фрагменты. Управление анализом — сверху. Исходные фразы уже доступны.";list.addView(label(pending,15));text.append(pending).append('\n');}
  int count=0;for(String group:new String[]{"discussion","decision","promise","task","question","risk"}){int found=0;Set<String> unique=new HashSet<>();List<Runnable> cards=new ArrayList<>();StringBuilder section=new StringBuilder();for(Entry e:entries){JSONArray points=e.state.optJSONArray("items");if(points==null)continue;for(int n=0;n<points.length();n++){JSONObject p=points.optJSONObject(n);if(p==null||line(e,p)==null||!matches(e,p,filter))continue;String kind=p.optString("kind");if("discussion".equals(group)?!("topic".equals(kind)||"fact".equals(kind)):!group.equals(kind))continue;TaskDb.Row row="task".equals(kind)?task(e,p):null;if(row!=null&&row.completed)continue;String point=pointText(e,p);String source=sessionTitle(e.dir)+" · "+p.optString("time");String key=point.toLowerCase(Locale.ROOT);if(!unique.add(key))continue;found++;if(!full&&found>3)continue;section.append("• ").append(point).append("\nИсточник: ").append(source).append("\n«").append(p.optString("quote")).append("»\n");cards.add(()->{list.addView(label("• "+point,16));button(list,"Источник: "+source,()->source(e,p));});}}
   if(found>0){String heading=title("discussion".equals(group)?"topic":group);list.addView(label(heading,19));text.append('\n').append(heading).append(":\n").append(section);for(Runnable card:cards)card.run();count+=found;if(!full&&found>3){final int extra=found-3;button(list,"Показать ещё "+extra,()->detailed.setChecked(true));text.append("Ещё пунктов: ").append(extra).append(". Включи подробный вид.\n");}}
  }
  if(total>0&&count==0){String empty=filter.isEmpty()?(processed==total?"В готовом разборе нет содержательных выводов за этот период. Исходные разговоры доступны ниже.":"Готовых выводов за этот период пока нет."):"В сводке совпадений нет. Попробуй другое имя или слово; исходные разговоры доступны ниже.";list.addView(label(empty,16));text.append(empty).append('\n');}
  for(Entry e:entries)if(!e.state.optString("error").isEmpty())list.addView(label("Запись "+sessionTitle(e.dir)+": "+e.state.optString("error"),14));report=text.toString();
 }
 private void rawPeriod(){RecallWindow window=new RecallWindow(selected,ZoneId.systemDefault());String caption=period();new Thread(()->{StringBuilder raw=new StringBuilder();try{for(File dir:dirs()){boolean heading=false;for(ConversationAnalysis.Line l:ConversationAnalysis.read(dir))if(window.contains(l.recorded)){if(!heading){raw.append("\nЗапись ").append(sessionTitle(dir)).append('\n');heading=true;}raw.append('[').append(l.time).append("] ").append(l.text).append('\n');}}}catch(Exception e){raw.append("\nОшибка чтения: ").append(e.getMessage());}String value=raw.length()==0?"За этот период записей нет":raw.toString();runOnUiThread(()->{if(!isFinishing())showText(caption,value);});},"recall-originals").start();}
 private void showText(String title,String value){TextView t=label(value,16);ScrollView scroll=new ScrollView(this);scroll.addView(t);new AlertDialog.Builder(this).setTitle(title).setView(scroll).setPositiveButton("Закрыть",null).setNeutralButton("Скопировать",(d,w)->copy(value)).show();}
 private void source(Entry e,JSONObject p){String value=pointText(e,p)+"\n\nИсходная реплика "+p.optInt("line")+" · "+p.optString("time")+"\n«"+p.optString("quote")+"»";TextView t=label(value,17);ScrollView scroll=new ScrollView(this);scroll.addView(t);new AlertDialog.Builder(this).setTitle(sessionTitle(e.dir)).setView(scroll).setPositiveButton("Закрыть",null).setNeutralButton("Скопировать пункт",(d,w)->copy(value)).setNegativeButton("Скопировать цитату",(d,w)->copy(p.optString("quote"))).show();}
 private void copy(String value){getSystemService(android.content.ClipboardManager.class).setPrimaryClip(ClipData.newPlainText("Вспомнить разговоры",value));Toast.makeText(this,"Скопировано",Toast.LENGTH_SHORT).show();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("day",selected==null?"":selected.toString());}
 @Override protected void onResume(){super.onResume();refreshed=0;handler.removeCallbacks(tick);handler.post(tick);if(LocalModel.ready(this)&&(getIntent().getStringExtra("session")!=null||getSharedPreferences("ai",0).getBoolean("pending",true))&&!getSharedPreferences("ai",0).getBoolean("paused",false))AnalysisService.startUser(this,getIntent().getStringExtra("session"));}
 @Override protected void onPause(){handler.removeCallbacks(tick);super.onPause();}
}
